def load_module(inference_state, dotted_name, sys_path):
    (temp, sys.path) = (sys.path, sys_path)
    try:
        try:
            __import__(dotted_name)
        except ImportError:
            warnings.warn('Module %s not importable in path %s.' % (dotted_name, sys_path), UserWarning, stacklevel=2)
            return None
        except Exception:
            warnings.warn('Cannot import:\n%s' % traceback.format_exc(), UserWarning, stacklevel=2)
            return None
    finally:
        sys.path = temp
    module = sys.modules[dotted_name]
    return create_access_path(inference_state, module)

